// src/constants/locks.js
//
// Clean-sheet sloten — afbeeldingen ingebed (geen losse bestanden nodig).
export const LOCKS = [
  { id:'kluis', naam:'Kluis', bestand:'data:image/png;base64,' },
  { id:'schild', naam:'Schild', bestand:'data:image/png;base64,' },
  { id:'hangslot', naam:'Hangslot', bestand:'data:image/png;base64,' },
];

export function getLock(id) {
  return LOCKS.find(l => l.id === id) || LOCKS[0];
}

export function randomLockId() {
  return LOCKS[Math.floor(Math.random() * LOCKS.length)].id;
}
